# 对标《高性价比人生指南》《高性价比投资指南》的逐条 mini-report 格式：
#   ### N. 标题 + <!-- 标签 --> + 成本/说人话/收益/证据等级/来源/备注
# 运行：python3 gen_出海指南.py  ->  高性价比出海指南.md
import datetime

chapters = []

def E(n, title, tags, cost, plain, gain, ev, src, note=""):
    return dict(n=n, title=title, tags=tags, cost=cost, plain=plain,
                gain=gain, ev=ev, src=src, note=note)

def ch(no, title, q, intro, entries):
    chapters.append(dict(no=no, title=title, q=q, intro=intro, entries=entries))

