def _flatten(chapters):
    import re
    data = []
    for c in chapters:
        for idx, e in enumerate(c["entries"], 1):
            evv = e["ev"].replace("证据等级：", "").strip()
            src_raw = _strip(e["src"], "来源：")
            urls = re.findall(r"https?://\S+", src_raw)
            url = urls[-1] if urls else ""
            note_raw = _strip(e["note"], "备注：") if e["note"] else ""
            data.append({"ch": c["no"], "ch_title": c["title"], "no": idx, "title": e["title"],
                         "tags": e["tags"], "cost": _strip(e["cost"], "成本："),
                         "plain": _strip(e["plain"], "说人话："), "gain": _strip(e["gain"], "收益："),
                         "ev": evv, "src": src_raw, "url": url, "note": note_raw})
    return data

def _card_html(e):
    tags = " ".join('<span class="tag">%s</span>' % _h(t) for t in (e["tags"] or "").split())
    note = '<div class="f"><span class="k">备注</span><span class="v">%s</span></div>' % _h(e["note"]) if e["note"] else ""
    link = ' <a class="src" href="%s" target="_blank" rel="noopener">↗ 来源</a>' % _h(e["url"]) if e["url"] else ""
    return ('<article class="card" style="border-left-color:%s">'
            '<div class="ch">第%s章 · %s</div>'
            '<h3><span class="badge" style="background:%s">%s</span> %s.%s %s</h3>'
            '<div class="tags">%s</div>'
            '<div class="f"><span class="k">成本</span><span class="v">%s</span></div>'
            '<div class="f"><span class="k">说人话</span><span class="v">%s</span></div>'
            '<div class="f"><span class="k">收益</span><span class="v">%s</span></div>'
            '<div class="f"><span class="k">证据等级</span><span class="v">%s</span></div>'
            '<div class="f"><span class="k">来源</span><span class="v">%s%s</span></div>'
            '%s</article>') % (
        GRADE_COLOR[e["ev"]], e["ch"], _h(e["ch_title"]), GRADE_COLOR[e["ev"]], GRADE_NAME[e["ev"]],
        e["ch"], e["no"], _h(e["title"]), tags, _h(e["cost"]), _h(e["plain"]), _h(e["gain"]),
        e["ev"], _h(e["src"]), link, note)

def _dest_sections(chapters):
    import re as _re
    data = _flatten(chapters)
    for e in data:
        src_clean = _re.sub(r"https?://\S+", "", e["src"])
        e["_hay"] = (e["title"] + e["plain"] + e["gain"] + src_clean + e["tags"] + e["ch_title"]).lower()
    sections = []
    for d in DEST_SPECS:
        # 负向后行断言：ASCII 关键词只在不被字母/数字紧跟时才算命中，
        # 避免 "IRS" 误中 "Home Affairs"、URL 子串等。
        pats = [r"(?<![a-z0-9])" + _re.escape(k.lower()) for k in d["kw"]]
        matches = [e for e in data if any(_re.search(p, e["_hay"]) for p in pats)]
        matches.sort(key=lambda e: (e["ch"], e["no"]))
        sections.append(dict(d, entries=matches))
    return sections

