def build_cards(chapters):
    sections = _dest_sections(chapters)
    tabs = '<button class="tab act" onclick="show(\'all\')">全部</button>'
    tabs += "".join('<button class="tab" onclick="show(\'%s\')">%s</button>' % (_h(s["name"]), _h(s["name"])) for s in sections)
    secs = ""
    for s in sections:
        cards = "".join(_card_html(e) for e in s["entries"])
        secs += ('<section class="dsec" data-dest="%s"><div class="dhead"><h2>%s</h2>'
                 '<span class="light">%s</span></div><p class="one">%s</p>'
                 '<p class="cnt">相关条目 %d 条</p><div class="grid">%s</div></section>') % (
            _h(s["name"]), _h(s["name"]), _h(s["light"]), _h(s["one"]), len(s["entries"]), cards)
    return CARDS_HEAD + '<div class="tabs">' + tabs + '</div><main>' + secs + '</main><footer>本页由《高性价比出海指南》自动聚合生成，内容以 CC BY 4.0 发布，并以官方最新发布为准。</footer>' + CARDS_BODY

def build_cards_md(chapters):
    sections = _dest_sections(chapters)
    L = ["# 分目的地出海速查卡", "",
         "> 《高性价比出海指南》按目的地的聚合视图。每条均可在正文按「章.条」编号核对。", ""]
    for s in sections:
        L.append("## %s · %s" % (s["name"], s["light"]))
        L.append("")
        L.append(s["one"])
        L.append("")
        if not s["entries"]:
            L.append("（暂无专门条目，见对应区域章与第 22 章红绿灯。）")
        for e in s["entries"]:
            L.append("- **%d.%d %s**（证据 %s）：%s" % (e["ch"], e["no"], e["title"], e["ev"], e["plain"]))
        L.append("")
    return "\n".join(L)

