TOOLBOX_SECTIONS = ('''<section class="tool"><h2>① 实体选择决策树</h2><p class="sub">回答几个问题，告诉你该走 ODI / 37号文 / 直接当地注册，以及要不要碰 GDPR。</p><div id="dt"></div></section>'''
'<section class="tool calc"><h2>② 出海成本估算器</h2><p class="sub">选目的地与业务形态，给「首年真实花费」区间（注册+年审+合规+税），仅供预算参考，以官方为准。</p><div class="row"><div><label>目的地</label><select id="c_country"></select></div><div><label>业务形态</label><select id="c_type"><option value="hold">控股 / IP 壳</option><option value="trade">贸易 / 电商</option><option value="ops">实体经营 + 雇人</option></select></div></div><button class="opt" style="margin-top:12px" onclick="calcCost()">估算</button><div class="out" id="c_out"></div><p class="disclaimer">费用为公开区间估算（2025–2026），含政府费+基础秘书/地址，不含业务本身投入；税率请咨询持牌税务师。</p></section>'
'<section class="tool"><h2>③ 出海前核对清单</h2><p class="sub">勾选已完成项，进度自动保存（本机浏览器）。分十大类逐项清，建议出海前 12–24 个月启动。</p><div class="bar"><i id="cl_bar"></i></div><div class="meta"><span id="cl_cnt">0/0</span> 已完成 · 数据仅存本机</div><div id="cl"></div><p style="margin-top:10px"><button class="opt" onclick="exportCL()">导出已勾选</button> <button class="opt" onclick="resetCL()">重置</button></p></section>'
'<section class="tool"><h2>④ 跨境合同模板库</h2><p class="sub">可直接复制使用的条款骨架。注意：模板非法律意见，正式签署前请当地律师过目。</p><div id="tpls"></div></section>''')

